begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(17);
insert into auth.users(id,email) values
('71000000-0000-4000-8000-000000000001','team-admin@example.com'),('71000000-0000-4000-8000-000000000002','team-manager@example.com'),('71000000-0000-4000-8000-000000000003','team-member@example.com'),('71000000-0000-4000-8000-000000000004','team-stakeholder@example.com'),('71000000-0000-4000-8000-000000000005','team-readonly@example.com'),('71000000-0000-4000-8000-000000000006','team-ordinary@example.com'),('71000000-0000-4000-8000-000000000007','team-inactive@example.com'),('71000000-0000-4000-8000-000000000008','team-other@example.com');
insert into profiles(id,email,full_name) select id,email,email from auth.users where id::text like '71000000-%';
insert into organizations(id,name,created_by) values('72000000-0000-4000-8000-000000000001','Team Test Org','71000000-0000-4000-8000-000000000001'),('72000000-0000-4000-8000-000000000002','Other Team Org','71000000-0000-4000-8000-000000000008');
insert into organization_members(organization_id,user_id,role,status) values
('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','Administrator','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Member','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Member','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004','Member','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000005','Member','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000006','Member','Active'),('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000007','Member','Inactive'),('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000008','Administrator','Active');
insert into projects(id,organization_id,name,business_objective,project_manager_id,sponsor_name,lifecycle_phase,status,start_date,target_completion_date,overall_health,scope_health,schedule_health,budget_health,resource_health,risk_health,created_by) values('73000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','Team Project','Test team access','71000000-0000-4000-8000-000000000002','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','71000000-0000-4000-8000-000000000001');
insert into project_members(project_id,user_id,project_role,access_level) values('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Project Manager','Project Manager');

select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Project Member',true)$$,'Administrator adds eligible member');
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Stakeholder',true)$$,'Administrator changes access');
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Stakeholder',false)$$,'Administrator deactivates');
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Read Only',true)$$,'Administrator reactivates existing membership');
select is((select count(*) from project_members where project_id='73000000-0000-4000-8000-000000000001' and user_id='71000000-0000-4000-8000-000000000003'),1::bigint,'Duplicate membership is prevented');
select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000008','Project Member',true)$$,'42501','The selected user is not an active organization member.','Cross-organization member cannot be added');
select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000007','Project Member',true)$$,'42501','The selected user is not an active organization member.','Inactive organization member cannot be added');
select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Read Only',false)$$,'42501','The assigned Project Manager membership is protected.','Assigned manager cannot be changed');
select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004','Project Manager',true)$$,'22023','Unsupported project access level.','Another manager cannot be granted');
reset role;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000002',true);set local role authenticated;
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004','Stakeholder',true)$$,'Assigned manager adds member');
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004','Read Only',true)$$,'Assigned manager changes access');
select lives_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000004','Read Only',false)$$,'Assigned manager deactivates member');
reset role;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000003',true);set local role authenticated;select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000005','Read Only',true)$$,'42501','Project team management is not permitted.','Project Member is denied');reset role;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000004',true);set local role authenticated;select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000005','Read Only',true)$$,'42501','Project team management is not permitted.','Stakeholder is denied');reset role;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000005',true);set local role authenticated;select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000006','Project Member',true)$$,'42501','Project team management is not permitted.','Read Only is denied');reset role;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000006',true);set local role authenticated;select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000005','Read Only',true)$$,'42501','Project team management is not permitted.','Ordinary member is denied');reset role;
select set_config('request.jwt.claim.role','anon',true);select set_config('request.jwt.claim.sub','',true);set local role anon;select throws_ok($$select manage_project_membership('73000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Project Member',true)$$,'42501','permission denied for function manage_project_membership','Anonymous access is denied');reset role;
select * from finish();rollback;
